attachment.snippet:
1	role: Aggregator
2	replicas: ${replicas}
3	podAnnotations:
4	  reloader.stakater.com/auto: "true"
5	service:
6	  enabled: true
7	  type: ClusterIP
8	  ports:
9	    - name: otlp-grpc
10	      port: 4317
11	      protocol: TCP
12	    - name: otlp-http
13	      port: 4318
14	      protocol: TCP
15	    - name: dd-agent
16	      port: 8282
17	      protocol: TCP
18	env:
19	  - name: DATADOG_API_KEY
20	    valueFrom:
21	      secretKeyRef:
22	        name: vector-datadog
23	        key: api_key
24	resources:
25	  requests:
26	    cpu: ${requests_cpu}
27	    memory: ${requests_memory}
28	  limits:
29	    cpu: "${limits_cpu}"
30	    memory: ${limits_memory}
31	podDisruptionBudget:
32	  enabled: true
33	  minAvailable: 2
34	
35	topologySpreadConstraints:
36	  - maxSkew: 1
37	    topologyKey: topology.kubernetes.io/zone
38	    whenUnsatisfiable: ScheduleAnyway
39	    labelSelector:
40	      matchLabels:
41	        app.kubernetes.io/name: vector
42	
43	affinity:
44	  podAntiAffinity:
45	    preferredDuringSchedulingIgnoredDuringExecution:
46	      - weight: 100
47	        podAffinityTerm:
48	          topologyKey: kubernetes.io/hostname
49	          labelSelector:
50	            matchLabels:
51	              app.kubernetes.io/name: vector
52	
53	%{ if service_monitor_enabled ~}
54	serviceMonitor:
55	  enabled: true
56	%{ endif ~}
57	customConfig:
58	  data_dir: /vector-data-dir
59	  api:
60	    enabled: true
61	    address: 0.0.0.0:8686
62	  sources:
63	    otlp_in:
64	      type: opentelemetry
65	      grpc:
66	        address: 0.0.0.0:4317
67	      http:
68	        address: 0.0.0.0:4318
69	    dd_agent_in:
70	      type: datadog_agent
71	      address: 0.0.0.0:8282
72	      multiple_outputs: true
73	      disable_metrics: true
74	      disable_traces: true
75	      store_api_key: false
76	      acknowledgements:
77	        enabled: true
78	  transforms:
79	    drop_audit:
80	      type: filter
81	      inputs:
82	        - otlp_in.logs
83	        - dd_agent_in.logs
84	      condition: |
85	        msg = if is_string(.message) { string!(.message) } else { "" }
86	        ${audit_drop_condition}
87	    normalize_logs:
88	      type: remap
89	      inputs:
90	        - drop_audit
91	      source: |
92	        if exists(.severity) {
93	          .status = downcase(to_string!(.severity))
94	          del(.severity)
95	        }
96	%{ if email_do_redact ~}
97	    redact_emails_logs:
98	      type: remap
99	      inputs:
100	        - normalize_logs
101	      source: |
102	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
103	        if is_string(.message) {
104	          .message = replace(string!(.message), email_re, "${email_redaction_replacement}")
105	        }
106	        if is_object(.attributes) {
107	          attrs, _err = object(.attributes)
108	          if is_object(attrs) {
109	            .attributes = map_values(attrs) -> |v| {
110	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
111	            }
112	          }
113	        }
114	%{ endif ~}
115	%{ if email_do_tag ~}
116	    tag_emails_logs:
117	      type: remap
118	      inputs:
119	        - normalize_logs
120	      source: |
121	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
122	        detected = false
123	        if is_string(.message) {
124	          detected = match(string!(.message), email_re)
125	        }
126	        if !detected && is_object(.attributes) {
127	          detected = match(encode_json(.attributes), email_re)
128	        }
129	        if detected {
130	          .ddtags = if is_string(.ddtags) { string!(.ddtags) + ",vector_redaction:true" } else { "vector_redaction:true" }
131	        }
132	%{ endif ~}
133	%{ if bearer_do_redact ~}
134	    redact_bearer_tokens_logs:
135	      type: remap
136	      inputs:
137	        - ${bearer_token_logs_input}
138	      source: |
139	        bearer_re = r'(?i)Bearer\s+[A-Za-z0-9+/._~-]+=*'
140	        svc = to_string(.service) ?? ""
141	        ddtags = to_string(.ddtags) ?? ""
142	        msg = if is_string(.message) { string!(.message) } else { "" }
143	%{ if bearer_needs_combined ~}
144	        combined = msg + " " + ddtags
145	%{ endif ~}
146	        target_services = ${bearer_token_services_arr}
147	        should_redact = contains(ddtags, "env:prod") && includes(target_services, svc) && ${bearer_token_exclusion_condition}
148	        if should_redact && is_string(.message) {
149	          .message = replace(string!(.message), bearer_re, "${bearer_token_redaction_replacement}")
150	        }
151	%{ endif ~}
152	%{ if bearer_do_tag ~}
153	    tag_bearer_tokens_logs:
154	      type: remap
155	      inputs:
156	        - ${bearer_token_logs_input}
157	      source: |
158	        bearer_re = r'(?i)Bearer\s+[A-Za-z0-9+/._~-]+=*'
159	        svc = to_string(.service) ?? ""
160	        ddtags = to_string(.ddtags) ?? ""
161	        msg = if is_string(.message) { string!(.message) } else { "" }
162	%{ if bearer_needs_combined ~}
163	        combined = msg + " " + ddtags
164	%{ endif ~}
165	        target_services = ${bearer_token_services_arr}
166	        would_redact = contains(ddtags, "env:prod") && includes(target_services, svc) && ${bearer_token_exclusion_condition}
167	        if would_redact && is_string(.message) && match(string!(.message), bearer_re) {
168	          .ddtags = if is_string(.ddtags) { string!(.ddtags) + ",vector_redaction:true" } else { "vector_redaction:true" }
169	        }
170	%{ endif ~}
171	%{ if aws_key_do_redact ~}
172	    redact_aws_access_keys_logs:
173	      type: remap
174	      inputs:
175	        - ${aws_key_logs_input}
176	      source: |
177	        aws_key_re = r'(AKIA|ASIA|AROA|AIPA|ANPA|ANVA|APKA)[A-Z0-9]{16}'
178	        svc = to_string(.service) ?? ""
179	        ddtags = to_string(.ddtags) ?? ""
180	        msg = if is_string(.message) { string!(.message) } else { "" }
181	%{ if aws_key_needs_combined ~}
182	        combined = msg + " " + ddtags
183	%{ endif ~}
184	        target_services = ${aws_key_services_arr}
185	        attr_excluded = ${aws_key_attr_exclusion_condition}
186	        should_redact = contains(ddtags, "env:prod") && includes(target_services, svc) && ${aws_key_string_exclusion_condition} && !attr_excluded
187	        if should_redact && is_string(.message) {
188	          .message = replace(string!(.message), aws_key_re, "${aws_access_key_redaction_replacement}")
